cat > src/server/db.ts <<'EOF'
import { readdir, readFile } from 'node:fs/promises';
import pg from 'pg';

// pg turns a `date` into local midnight, which shifts a day in zones east of UTC. Keep it a plain 'YYYY-MM-DD'.
pg.types.setTypeParser(pg.types.builtins.DATE, (v) => v);

const MIGRATION_LOCK = 727001;

export function createPool(connectionString: string, max?: number): pg.Pool {
  const pool = new pg.Pool({ connectionString, max });
  pool.on('error', (err: Error & { code?: string }) => {
    // 57P01: the server ended an idle connection, as a test teardown's `drop database ... with (force)` does.
    if (err.code !== '57P01') console.error('postgres pool error', err);
  });
  return pool;
}

export async function migrate(pool: pg.Pool): Promise<string[]> {
  const dir = new URL('../../migrations/', import.meta.url);
  const client = await pool.connect();
  try {
    await client.query('select pg_advisory_lock($1)', [MIGRATION_LOCK]);
    await client.query(
      'create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now())',
    );
    const done = new Set((await client.query('select name from schema_migrations')).rows.map((r) => r.name));
    const applied: string[] = [];
    for (const name of (await readdir(dir)).filter((f) => f.endsWith('.sql')).sort()) {
      if (done.has(name)) continue;
      const sql = await readFile(new URL(name, dir), 'utf8');
      try {
        await client.query('begin');
        await client.query(sql);
        await client.query('insert into schema_migrations (name) values ($1)', [name]);
        await client.query('commit');
      } catch (err) {
        await client.query('rollback');
        throw err;
      }
      applied.push(name);
    }
    return applied;
  } finally {
    try {
      await client.query('select pg_advisory_unlock($1)', [MIGRATION_LOCK]);
    } finally {
      client.release();
    }
  }
}
EOF
cat > src/server/test-db.ts <<'EOF'
import { randomBytes } from 'node:crypto';
import type pg from 'pg';
import { createPool, migrate } from './db.ts';

export type TestDb = { pool: pg.Pool; drop(): Promise<void> };

const hex = () => randomBytes(6).toString('hex');

// A throwaway, fully migrated database, so every test file runs against its own data.
export async function createTestDb(): Promise<TestDb> {
  const adminUrl = process.env.DATABASE_URL ?? 'postgres://bookings:bookings@localhost:5433/bookings';
  const name = `t_${hex()}`;
  const admin = createPool(adminUrl, 1);
  await admin.query(`create database "${name}"`);
  const url = new URL(adminUrl);
  url.pathname = `/${name}`;
  const pool = createPool(url.toString(), 40); // 40 connections for the race tests
  const drop = async () => {
    await pool.end();
    await admin.query(`drop database "${name}" with (force)`);
    await admin.end();
  };
  try {
    await migrate(pool);
  } catch (err) {
    await drop();
    throw err;
  }
  return { pool, drop };
}

export async function insertMentor(
  pool: pg.Pool,
  m: { name?: string; timeZone: string; hours: { weekday: number; start: string; end: string }[] },
): Promise<number> {
  const { rows } = await pool.query(
    `insert into mentors (name, email, time_zone, bio, subjects) values ($1, $2, $3, 'Test mentor', '{Coding}') returning id`,
    [m.name ?? 'Test Mentor', `m-${hex()}@mentors.example`, m.timeZone],
  );
  const id: number = rows[0].id;
  for (const h of m.hours) {
    await pool.query('insert into mentor_hours (mentor_id, weekday, start_time, end_time) values ($1, $2, $3, $4)', [
      id,
      h.weekday,
      h.start,
      h.end,
    ]);
  }
  return id;
}
EOF
npx vitest run src/server/db.test.ts 2>&1 | tail -25

